import { useCallback, useMemo } from 'react'
import LazyLoad from 'react-lazyload'
import { connect } from 'react-redux'
import { Carousel } from 'react-responsive-carousel'
import 'react-responsive-carousel/lib/styles/carousel.min.css'
import {
  APR_21_2026_ANNOUNCEMENT,
  APR_21_2026_ANNOUNCEMENT_DETAIL,
  LV_PROPERTY_MAR_2026_BANNER,
  LV_PROPERTY_MAR_2026_BANNER_DETAIL,
  FLEET_SLA_MAY_2026_BANNER,
  FLEET_SLA_MAY_2026_BANNER_DETAIL,
  CLAIM_PORTAL_JUN_2026_BANNER,
  CLAIM_PORTAL_JUN_2026_BANNER_DETAIL,
  DYNAMIC_PPW_BANNER,
  DYNAMIC_PPW_BANNER_DETAIL,
  CLAIM_WHATSAPP_BANNER,
  CLAIM_WHATSAPP_BANNER_DETAIL,
  XENDIT_PAYMENT_BANNER,
  XENDIT_PAYMENT_BANNER_DETAIL,
  PLATFORM_FEE_BREAKDOWN_BANNER,
  PLATFORM_FEE_INFORMATION_BANNER,
  PLATFORM_FEE_INFORMATION_BANNER_DETAIL,
  PLATFORM_FEE_BREAKDOWN_BANNER_DETAIL,
  AGENCY_CLOSED_BANNER,
  AGENCY_CLOSED_BANNER_DETAIL,
} from '../../../../../images'
import { LANG_STRINGS } from '../../../../../lang'
import { Row } from '../../../../../commonStyle/index.style'
import Heading from '../../../../../components/Heading'
import { checkIsLvAdmin, checkIsLvAgent } from '../../../../../helpers/checkAgentTags'
import { PromoCarouselStyle } from './index.style'

function PromoCarousel({ onPromoModal, agentDetails }) {

  const banners = useMemo(() => {
    const lvBlueBanners = [
      {
        title: 'Platform Fee Announcement',
        banner: PLATFORM_FEE_INFORMATION_BANNER,
        imgUrl: PLATFORM_FEE_INFORMATION_BANNER_DETAIL,
        id: 'platform-fee-announcement',
      },
      {
        title: 'Platform Fee Breakdown Announcement',
        banner: PLATFORM_FEE_BREAKDOWN_BANNER,
        imgUrl: PLATFORM_FEE_BREAKDOWN_BANNER_DETAIL,
        id: 'platform-fee-breakdown-announcement',
      },
      {
        title: 'Claim Portal Jun 2026 Announcement',
        banner: CLAIM_PORTAL_JUN_2026_BANNER,
        imgUrl: CLAIM_PORTAL_JUN_2026_BANNER_DETAIL,
        id: 'claim-portal-jun-2026-announcement',
      },
      {
        title: 'Fleet SLA May 2026 Announcement',
        banner: FLEET_SLA_MAY_2026_BANNER,
        imgUrl: FLEET_SLA_MAY_2026_BANNER_DETAIL,
        id: 'fleet-sla-may-2026-announcement',
      },
      {
        title: 'Apr 21 2026 Announcement',
        banner: APR_21_2026_ANNOUNCEMENT,
        imgUrl: APR_21_2026_ANNOUNCEMENT_DETAIL,
        id: 'apr-21-2026-announcement',
      },
      {
        title: 'Mar 2026 Property Campaign',
        banner: LV_PROPERTY_MAR_2026_BANNER,
        imgUrl: LV_PROPERTY_MAR_2026_BANNER_DETAIL,
        id: 'mar-2026-property-banner',
      },
      {
        title: 'Pembaruan Platform Pembayaran',
        banner: XENDIT_PAYMENT_BANNER,
        imgUrl: XENDIT_PAYMENT_BANNER_DETAIL,
        id: 'xendit-payment-banner',
      },
      {
        title: 'dynamic ppw banner',
        banner: DYNAMIC_PPW_BANNER,
        imgUrl: DYNAMIC_PPW_BANNER_DETAIL,
        id: 'dynamic-ppw-banner',
      },
      {
        title: 'claim whatsapp banner',
        banner: CLAIM_WHATSAPP_BANNER,
        imgUrl: CLAIM_WHATSAPP_BANNER_DETAIL,
        id: 'claim-whatsapp-banner',
      },
    ]
    const banners = [
      {
        title: 'Agency Closed Banner',
        banner: AGENCY_CLOSED_BANNER,
        imgUrl: AGENCY_CLOSED_BANNER_DETAIL,
        id: 'agency-closed-banner',
      },
    ]
    if (checkIsLvAgent(agentDetails) || checkIsLvAdmin(agentDetails)) {
      return lvBlueBanners
    }
    return banners
  }, [agentDetails])

  const showModal = useCallback(
    (banner) => {
      if (banner.disable) return
      onPromoModal({
        title: banner.title,
        imgUrl: banner.imgUrl,
        showBtn: false,
        ...banner,
      })
    },
    [onPromoModal]
  )

  return (
    <PromoCarouselStyle>
      <Heading className="promo-heading" title={LANG_STRINGS.mitraInfo} />
      <Carousel showThumbs={false} showStatus={false} showArrows centerMode showIndicators={false}>
        {banners.map((banner) => (
          <Row
            id={banner.id}
            key={banner.id}
            onClick={() => showModal(banner)}
            data-gtm-banner-id={banner.title}
            data-gtm-element-id="promo-carousel"
          >
            <LazyLoad height={160} once>
              <div data-gtm-banner-id={banner.title} data-gtm-element-id="promo-carousel">
                <img
                  data-gtm-banner-id={banner.title}
                  data-gtm-element-id="promo-carousel"
                  src={banner.banner}
                  width={250}
                  alt={banner.title}
                  loading="lazy"
                />
              </div>
            </LazyLoad>
          </Row>
        ))}
      </Carousel>
    </PromoCarouselStyle>
  )
}

export default connect((state) => ({
  agentDetails: state.User.agentDetails,
}))(PromoCarousel)
